const fs=require('fs'),path=require('path');let timer,running=false,tries=0;
exports.load=()=>{timer=setInterval(async()=>{if(running)return;running=true;const out={};try{for(const op of ['query-is-ready','query-current-scene','query-scene-mode','query-dirty','query-node-tree']){try{out[op]=await Editor.Message.request('scene',op);}catch(e){out[op]={error:String(e)};}}out.scene=await Editor.Message.request('scene','execute-scene-script',{name:'p3-probe',method:'probe',args:[Editor.Project.path]});await Editor.Message.request('asset-db','refresh-asset','db://assets/Qualification.scene');const uuid=await Editor.Message.request('asset-db','query-uuid','db://assets/Qualification.scene');await Editor.Message.request('scene','open-scene',uuid);for(const op of ['query-current-scene','query-scene-mode','query-dirty','query-node-tree'])out['opened-'+op]=await Editor.Message.request('scene',op);fs.writeFileSync(path.join(__dirname,'../../../probe.json'),JSON.stringify(out,null,2));if(out.scene)clearInterval(timer);}catch(e){fs.writeFileSync(path.join(__dirname,'../../../probe-error.json'),JSON.stringify({error:String(e.stack),tries:++tries}));if(tries>30)clearInterval(timer);}finally{running=false;}},2000);};exports.unload=()=>clearInterval(timer);
